#!/usr/bin/env python3
"""Actual renderer comparisons for three different terrain transition recipes."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
LIB=ROOT/'docs/design/terrain-transition-022'
VIEWS=[('everest','珠峰 · 山麓过渡'),('dunes','沙丘 · 风沙过渡'),('tigris','河曲 · 河漫滩过渡'),('city_delhi','德里周边'),('city_panti','盘橐城周边'),('city_baghdad','巴格达周边'),('central','丝路与高原'),('overview','星球总览')]
def main():
    options=''.join(f'<option value="{k}">{v}</option>' for k,v in VIEWS)
    template='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>丝路星球 · 景点与地表的过渡</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f0e7;color:#344238;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1380px;margin:auto;padding:40px 34px 42px}.eyebrow{font-size:11px;letter-spacing:.13em;color:#7d826f}h1{font-size:clamp(27px,4vw,43px);font-weight:560;line-height:1.4;margin:17px 0 13px}p{font-size:14px;line-height:1.9;color:#78816e;max-width:940px}.notice{border-left:3px solid #86976d;background:#e7eadc;border-radius:4px;padding:13px 17px;font-size:12px;line-height:1.85;margin:23px 0}.controls{display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap;margin:20px 0 12px}select,button{font:inherit;font-size:13px;color:inherit;background:#faf9f2;border:1px solid #cbd0bf;border-radius:4px;padding:9px 13px;cursor:pointer}.buttons{display:flex;gap:6px}button.active{background:#dce5d0;border-color:#a7b991}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #a77d36;outline-offset:3px}.comparison{aspect-ratio:16/9;position:relative;overflow:hidden;border-radius:7px;background:#092238;--split:50%}.comparison img{position:absolute;width:100%;height:100%;object-fit:contain;display:block}.comparison .before{clip-path:inset(0 calc(100% - var(--split)) 0 0)}.divider{position:absolute;inset:0 auto 0 var(--split);width:2px;background:#eee9c4;pointer-events:none}.divider:after{content:'↔';position:absolute;top:48%;left:-17px;width:36px;height:36px;display:grid;place-items:center;color:#354335;background:#efeccc;border-radius:50%}.badges{position:absolute;top:12px;left:12px;right:12px;display:flex;justify-content:space-between;pointer-events:none}.badge{background:#eae8dbe8;color:#45513c;font-size:11px;padding:6px 10px;border-radius:3px}.scrub{display:flex;align-items:center;gap:14px;margin:13px 0}.scrub label{font-size:12px;white-space:nowrap;color:#79836d}input[type=range]{width:100%;accent-color:#82956c}.caption{font-size:12px;margin:7px 0 25px;max-width:none}.caption a{color:#536647;text-underline-offset:4px}.recipes{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;border-top:1px solid #d5d9c9;padding-top:25px;margin-top:24px}.recipe span{font-size:11px;color:#a0845a}.recipe h2{font-size:19px;font-weight:550;margin:11px 0}.recipe p{font-size:12px;margin:0;line-height:1.9}.recipe strong{font-weight:550;color:#57684a}footer{border-top:1px solid #d5d9c9;margin-top:28px;padding-top:20px;font-size:12px;line-height:2;color:#78816e}footer a{color:inherit;text-underline-offset:4px}@media(max-width:720px){main{padding:28px 18px}.recipes{grid-template-columns:1fr;gap:24px}.comparison{margin:0 -8px}.badge{font-size:10px;padding:4px 7px}.buttons{gap:4px}button{padding:8px 10px;font-size:12px}}
</style></head><body><main><div class="eyebrow">SILK ROAD / TERRAIN TRANSITIONS 022</div><h1>景点与地图之间，补上地貌的过渡。</h1><p>保留特色景点的主轮廓，让山脚、沙丘边缘与河岸向周围地表逐渐展开。先比较三种不同的过渡形态，再决定全图的制作方式。</p><div class="notice">Blender模型过渡版：两侧均为021布局，地理位置、比例、镜头和灯光一致；新模型按实际地面校准落地高度。主体与过渡地形可分别编辑，只试做珠峰、塔克拉玛干沙丘、底格里斯河曲三处，未接入正式地图。全图其余地标和4处岸形预留仍待处理。</div><div class="controls"><select id="view" aria-label="查看过渡样区">OPTIONS</select><div class="buttons"><button data-mode="before">原布局</button><button data-mode="compare" class="active">拖动对照</button><button data-mode="after">过渡样板</button></div></div><div class="comparison" id="comparison"><img id="after" src="previews/everest-after.jpg" alt="珠峰过渡样板实机画面"><img id="before" class="before" src="previews/everest-before.jpg" alt="珠峰原布局实机画面"><div class="divider" id="divider"></div><div class="badges"><span id="before-label" class="badge">原布局021</span><span id="after-label" class="badge">过渡样板022</span></div></div><div class="scrub"><label for="split">左右对照</label><input id="split" type="range" min="0" max="100" value="50" aria-label="前后画面对照分界"></div><p class="caption"><span id="caption">珠峰 · 山麓过渡</span> · Godot实际渲染 · <a id="before-full" href="previews/everest-before.jpg" target="_blank" rel="noopener">原图全尺寸</a> · <a id="after-full" href="previews/everest-after.jpg" target="_blank" rel="noopener">样板全尺寸</a></p><section class="recipes"><article class="recipe"><span>01 / 山地</span><h2>山峰 → 山麓 → 平地</h2><p>由主峰下延两三条低岩肩，在谷口铺开碎石扇坡。<strong>高峰保持锐利，脚部逐渐变低、变宽。</strong>过渡避开商道和相邻城市。</p></article><article class="recipe"><span>02 / 荒漠</span><h2>沙脊 → 低沙舌 → 沙地</h2><p>沿既有沙脊方向拉出低沙舌与浅鞍部，让黄沙色与周边荒漠接近。<strong>风向决定形状，外缘不做等宽圆圈。</strong></p></article><article class="recipe"><span>03 / 河谷</span><h2>河曲 → 河漫滩 → 原野</h2><p>顺上下游展开不对称岸带，内弯放低沙滩，外弯保留窄岸肩。<strong>先连地势与地色，河道端部的完整衔接另验。</strong></p></article></section><footer><a href="README.md">样板判断与制作边界</a> · <a href="transition-recipes.md">33件地标的过渡方案</a> · <a href="../map-layout-021/index.html">上一版完整布局</a><br>画面用于比较地貌关系，不代表正式性能、动态遮挡或全图接缝验收。</footer></main><script>
const titles=TITLES;const view=document.querySelector('#view'),split=document.querySelector('#split'),comparison=document.querySelector('#comparison');
function setSplit(value){split.value=value;comparison.style.setProperty('--split',value+'%');document.querySelector('#divider').style.display=value>0&&value<100?'block':'none';document.querySelector('#before-label').style.visibility=value>0?'visible':'hidden';document.querySelector('#after-label').style.visibility=value<100?'visible':'hidden';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===(value==100?'before':value==0?'after':'compare')))}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setSplit(b.dataset.mode==='before'?100:b.dataset.mode==='after'?0:50));split.oninput=()=>setSplit(Number(split.value));view.onchange=()=>{for(const phase of ['before','after']){document.querySelector('#'+phase).src='previews/'+view.value+'-'+phase+'.jpg';document.querySelector('#'+phase).alt=titles[view.value]+(phase==='before'?'原布局':'过渡样板')+'实机画面';document.querySelector('#'+phase+'-full').href='previews/'+view.value+'-'+phase+'.jpg'}document.querySelector('#caption').textContent=titles[view.value]};
</script></body></html>'''
    catalog=json.loads((LIB/'asset-catalog.json').read_text())
    names={'everest':'珠穆朗玛峰','taklamakan_dunes':'塔克拉玛干沙丘','tigris_meander':'底格里斯河曲'}
    cards=[]
    for a in catalog['assets']:
        aid=a['id']
        cards.append(f'''<article class="source-card"><a href="studio/{aid}-three-quarter.jpg" target="_blank" rel="noopener"><img loading="lazy" src="studio/{aid}-three-quarter.jpg" alt="{names[aid]}源模型三分之四视角"></a><h3>{names[aid]}</h3><p>主体与过渡分组编辑 · {a['triangles']:,} 三角面</p><a href="{a['glb']}" download>下载 GLB</a> · <a href="studio/{aid}-side.jpg" target="_blank" rel="noopener">侧面</a> · <a href="studio/{aid}-top.jpg" target="_blank" rel="noopener">俯视</a></article>''')
    source_section='''<section class="source-section"><h2>模型与过渡，一起编辑。</h2><p>以下是模型单独导入 Godot 的棚拍，不包含球面贴地。Blender 文件中每款各有一个场景，Hero 保留景点主体，Transition 单独编辑脚部地形。''' + '''<a href="source/transition-models.blend" download>下载可编辑 Blender 文件</a></p><div class="source-grid">'''+''.join(cards)+'''</div></section>'''
    css='''.source-section{margin-top:36px;border-top:1px solid #d5d9c9;padding-top:18px}.source-section h2{font-size:25px;font-weight:550}.source-section a{color:#536647;text-underline-offset:4px}.source-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.source-card img{display:block;width:100%;aspect-ratio:1;object-fit:cover;border-radius:6px}.source-card h3{font-size:17px;font-weight:550;margin:15px 0 5px}.source-card p{font-size:12px;margin:0 0 12px}.source-card a{font-size:12px}@media(max-width:720px){.source-grid{grid-template-columns:1fr}}'''
    template=template.replace('全图其余地标和4处岸形预留仍待处理。','当前判断：珠峰和沙丘的源模型可继续采用；地图脚坡的分面与河谷水口仍需修整。其他30款和4处岸形预留待处理。')
    template=template.replace('</style>',css+'</style>').replace('<footer>',source_section+'<footer>')
    (LIB/'index.html').write_text(template.replace('OPTIONS',options).replace('TITLES',json.dumps(dict(VIEWS),ensure_ascii=False)))
    print('022 comparison gallery created')
if __name__=='__main__':main()
